using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class GastonBachelard
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Au-dessus du sujet, au-delà de l’objet, la science moderne se fonde sur le projet. Dans la pensée scientifique, la méditation de l’objet par le sujet prend toujours la forme du projet.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La science de la réalité ne se contente plus du \"comment\" phénoménologique ; elle cherche le \"pourquoi\" mathématique.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Une expérience \"scientifique\" est […] alors une expérience qui \"contredit\" l'expérience \"commune\".", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La science est l'esthétique de l'intelligence.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La connaissance du réel est une lumière qui projette toujours quelque part des ombres.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le réel n'est jamais « ce qu'on pourrait croire » mais il est toujours ce qu'on aurait dû penser. La pensée empirique est claire, après coup, quand l'appareil des raisons a été mis au point. En revenant sur un passé d'erreurs, on trouve la vérité en un véritable repentir intellectuel. En fait, on connaît contre une connaissance antérieure, en détruisant des connaissances mal faites, en surmontant ce qui, dans l'esprit même, fait obstacle à la spiritualisation.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La science, dans son besoin d'achèvement comme dans son principe, s'oppose absolument à l'opinion. S'il lui arrive, sur un point particulier, de légitimer l'opinion, c'est pour d'autres raisons que celles qui fondent l'opinion, de sorte que l'opinion a, en droit, toujours tort. L'opinion pense mal, elle ne pense pas, elle traduit des besoins, en connaissances. En désignant les objets par leur utilité, elle s'interdit de les connaître. On ne peut rien fonder sur l'opinion : il faut d'abord la détruire. Elle est le premier obstacle à surmonter. Il ne suffirait pas, par exemple, de la rectifier sur des points particuliers, en la maintenant, comme une sorte de morale provisoire, une connaissance vulgaire provisoire. L'esprit scientifique nous interdit d'avoir une opinion sur des questions que nous ne comprenons pas, sur des questions que nous ne savons pas formuler clairement. Avant tout il faut savoir poser des problèmes. Et quoi qu'on dise, dans la vie scientifique, les problèmes ne se posent pas d'eux-mêmes. C'est précisément ce sens du problème qui donne la marque du véritable esprit scientifique. Pour un esprit scientifique toute connaissance est une réponse a une question. S'il n'y a pas eu de question il ne peut pas avoir connaissance scientifique. Rien ne va de soi. Rien n'est donné. Tout est construit.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Face au réel, ce qu'on croit savoir clairement offusque ce qu'on devrait savoir. Quand il se présente à la culture scientifique, l'esprit n'est jamais jeune. Il est même très vieux, car il a l'âge de ses préjugés. Accéder à la science, c'est, spirituellement, rajeunir, c'est accepter une mutation brusque qui doit contredire un passé.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Ainsi toute culture scientifique doit commencer […] par une catharsis intellectuelle et affective.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Nous comprenons la Nature en lui résistant.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Une connaissance générale est presque fatalement une connaissance vague.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Loin de s'émerveiller, la pensée objective doit ironiser.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Il suffit que nous parlions d'un objet pour nous croire objectifs.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Il faut donc opposer à l'esprit poétique expansif, l'esprit scientifique taciturne pour lequel l'antipathie préalable est une saine précaution.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le feu est ainsi un phénomène privilégié qui peut tout expliquer. Si tout ce qui change lentement s'explique par la vie, tout ce qui change vite s'explique par le feu. Le feu est l'ultra-vivant. Le feu est intime et il est universel. Il vit dans notre cœur. Il vit dans le ciel. Il monte des profondeurs de la substance et s'offre comme un amour. Il redescend dans la matière et se cache, latent, contenu comme la haine et la vengeance.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le rêve chemine linéairement, oubliant son chemin en courant. La rêverie travaille en étoile. Elle revient à son centre pour lancer de nouveaux rayons.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le feu matérialise la fête des hommes. Aussi haut qu'on puisse remonter, la valeur gastronomique prime la valeur alimentaire et c'est dans la joie et non pas dans la peine que l'homme a trouvé son esprit. La conquête du superflu donne une excitation spirituelle plus grande que la conquête du nécessaire. L'homme est une création du désir, non pas une création du besoin.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Moins monotone et moins abstrait que l'eau qui coule, plus prompt même à croître et à changer que l'oiseau au nid surveillé chaque jour dans le buisson, le feu suggère le désir de changer, de brusquer le temps, de porter toute la vie à son terme, à son au-delà.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le rêve est plus fort que l'expérience.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'amour n'est qu'un feu à transmettre. Le feu n'est qu'un amour à surprendre.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Avant d'être le fils du bois, le feu est le fils de l'homme.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La manière dont on imagine est souvent plus instructive que ce qu'on imagine.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le complexe de Novalis est caractérisé par une conscience de la chaleur intime primant toujours une science toute visuelle de la lumière. Il est fondé sur une satisfaction du sens thermique et sur la conscience profonde du bonheur calorifique. La chaleur est un bien, une possession. Il faut la garder jalousement et n'en faire don qu'à un être élu qui mérite une communion, une fusion réciproque. La lumière joue et rit à la surface des choses, mais, seule, la chaleur \"pénètre\".", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Comme toute richesse, le feu est rêvé dans sa concentration.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'homme est peut-être le premier objet naturel où la nature essaie de se contredire. C'est d'ailleurs la raison pour laquelle l'activité humaine est en train de changer la face de la planète.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Pour être heureux, il faut penser au bonheur d'un autre.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La philosophie de la science physique est peut-être la seule philosophie qui s'applique en déterminant un dépassement de ses principes. Bref, elle est la seule philosophie qui soit vraiment ouverte. Toute autre philosophie pose ses principes comme intangibles, ses premières vérités comme totales et achevées. Toute autre philosophie se fait gloire de sa fermeture.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'esprit scientifique ne peut se constituer qu'en détruisant l'esprit non scientifique. Trop souvent le savant se confie à une pédagogie fractionnée alors que l'esprit scientifique devrait viser à une réforme subjective totale. Tout réel progrès dans la pensée scientifique nécessite une conversion.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "\"La philosophie du non\" se trouvera donc être non pas une attitude de refus, mais une attitude de conciliation", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Pour que nous ayons quelque garantie d'être du même avis, sur une idée particulière, il faut, pour le moins, que nous n'ayons pas été du même avis. Deux hommes, s'ils veulent s'entendre vraiment, ont dû d'abord se contredire. La vérité est fille de la discussion, non pas fille de la sympathie.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "\"La Philosophie du non\" n'est pas une volonté de négation", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La généralisation par le ‘’non’’ doit inclure ce qu’elle nie. En fait, tout l'essor de la pensée scientifique depuis un siècle provient de telles généralisations dialectiques avec enveloppement de ce qu'on nie. Ainsi la géométrie non-euclidienne enveloppe la géométrie euclidienne ; la mécanique non-newtonienne enveloppe la mécanique newtonienne ; la mécanique ondulatoire enveloppe la mécanique relativiste.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Au fond de la matière pousse une végétation obscure ; dans la nuit de la matière fleurissent des fleurs noires. Elles ont déjà leurs velours et la formule de leur parfum.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La mort quotidienne n'est pas la mort exubérante du feu qui perce le ciel de ses flèches ; la mort quotidienne est la mort de l'eau. L'eau coule toujours, l'eau tombe toujours, elle finit toujours en sa mort horizontale. Dans d'innombrables exemples nous verrons que pour l'imagination matérialisante la mort de l'eau est plus songeuse que la mort de la terre : la peine de l'eau est infinie.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "C'est près de l'eau que j'ai le mieux compris que la rêverie est un univers en émanation, un souffle odorant qui sort des choses par l'intermédiaire d'un rêveur. Si je veux étudier la vie des images de l'eau, il me faut donc rendre leur rôle dominant à la rivière et aux sources de mon pays. Je suis né dans un pays de ruisseaux et de rivières, dans un coin de Champagne vallonnée, dans le Vallage, ainsi nommé à cause du grand nombre de ses vallons. La plus belle des demeures serait pour moi au creux d'un vallon, au bord d'une eau vive, dans l'ombre courte des saules et des osières.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'être voué à l'eau est un être en vertige. Il meurt à chaque minute.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'individu n'est pas la somme de ses impressions générales, il est la somme de ses impressions singulières.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "C'est en se tenant assez longtemps à la surface irisée que nous comprendrons le prix de la profondeur.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Plus qu'aucun autre élément peut-être, l'eau est une réalité poétique complète. Une poétique de l'eau, malgré la variété de ses spectacles, est assurée d'une unité. L'eau doit suggérer au poète une obligation nouvelle : ''l'unité d'élément''. Faute de cette unité d'élément, l'imagination matérielle n'est pas satisfaite et l'imagination formelle n'est pas suffisante pour lier les traits disparates. L'œuvre manque de vie parce qu'elle manque de substance.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'imagination n'est pas, comme le suggère l'étymologie, la faculté de former des images de la réalité ; elle est la faculté de former des images qui dépassent la réalité, qui \"chantent la réalité\". Elle est une faculté de surhumanité.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Une psychologie de l'esprit en action est automatiquement la psychologie d'un esprit exceptionnel, la psychologie d'un esprit que tente l'exception : l'image nouvelle greffée sur une image ancienne.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "[...] le narcissisme n'est pas toujours névrosant. Il joue ainsi un rôle positif dans l'œuvre esthétique, et par des transpositions rapides, dans l'œuvre littéraire. La sublimation n'est pas toujours la négation d'un désir ; elle ne se présente pas toujours comme une sublimation \"contre\" des instincts. Elle peut être une sublimation \"pour\" un idéal.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La vie réelle se porte mieux si on lui donne ses justes vacances d'irréalité.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'examen de l'imagination nous conduit à ce paradoxe : dans l'imagination de la vision généralisée, l'eau joue un rôle inattendu. L'œil véritable de la terre, c'est l'eau. Dans nos yeux, c'est l'eau qui rêve. Nos yeux ne sont-ils pas « cette flaque inexplorée de lumière liquide que Dieu a mise au fond de nous-mêmes » ? [Claudel, ''L'Oiseau noir dans le Soleil levant''].", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Devant l'eau profonde, tu choisis ta vision ; tu peux voir à ton gré le fond immobile ou le courant, la rive ou l'infini ; tu as le droit ambigu de voir et de ne pas voir ; tu as le droit de vivre avec le batelier ou de vivre avec « une race nouvelle de fées laborieuses, douées d'un goût parfait, magnifiques et minutieuses ». La fée des eaux, gardienne du mirage, tient tous les oiseaux du ciel dans sa main. Une flaque contient un univers. Un instant de rêve contient une âme entière.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Dans la rêverie d'Edgar Poe, pour un rêveur vivant, fidèle à la clairvoyance du rêve, comme Edgar Poe, une des fonctions du végétal est de produire de l'ombre comme la seiche produit de l'encre. A chaque heure de sa vie la forêt doit aider la nuit à noircir le monde.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'eau est ''l'élément'' de la mort jeune et belle, de la mort fleurie, et, dans les drames de la vie et de la littérature, elle est ''l'élément'' de la mort sans orgueil ni vengeance, du suicide masochiste.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La barque de Charon va toujours aux enfers. Il n'y a pas de nautonier du bonheur.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Comme le dit Salvador Dalí, la « montre molle » est chair, elle est « fromage ». Ces déformations sont souvent mal comprises parce qu'elles sont vues statiquement. Certains critiques ''stabilisés'' les prennent aisément pour des insanies. Ils n'en vivent pas la force onirique profonde, ils ne participent pas à l'imagination de riche viscosité qui donne parfois à un clin d'œil le bénéfice d'une divine lenteur.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Si la ''provocation'' est une notion indispensable pour comprendre le rôle actif de notre connaissance du monde, c'est qu'on ne fait pas de la psychologie avec de la défaite. On ne connaît pas tout de suite le monde dans une connaissance placide, passive, quiète. Toutes les rêveries constructives — et il n'est rien de plus essentiellement constructeur que la rêverie de puissance — s'animent dans l'espérance d'une adversité surmontée, dans la vision d'un adversaire vaincu. On ne trouvera le sens vital, nerveux, réel des notions objectives qu'en faisant l'histoire psychologique d'une victoire orgueilleuse remportée sur un élément adverse. C'est l'orgueil qui donne à l'unité dynamique à l'être, c'est lui qui crée et allonge la fibre nerveuse. C'est l'orgueil qui donne à l'élan vital ses trajets rectilignes, c'est-à-dire son succès absolu. C'est le sentiment de la victoire certaine qui donne au réflexe sa flèche, la joie souveraine, la joie mâle de perforer la réalité.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "[[Friedrich Nietzsche|Nietzsche]] a instruit patiemment sa volonté de puissance par ses longues marches dans la montagne, par sa vie en plein vent sur les sommets. Sur les sommets, il a aimé : « L'âpre divinité de la roche sauvage ». La pensée dans le vent ; il a fait de la marche un combat. Mieux, ''la marche est son combat''. C'est elle qui donne le rythme énergétique de Zarathoustra. Zarathoustra ne parle pas assis, il ne parle pas en se promenant, comme un péripatéticien. Il donne sa doctrine en marchant énergiquement. Il la jette aux quatre vents du ciel.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Les larmes du ''marcheur combattant'' ne sont pas de l'ordre des peines, elles sont de l'ordre de la rage. Elles répondent par la colère à la colère de la tempête. Le vent ''vaincu'' les essuiera.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La marche contre le vent, la marche dans la montagne est sans doute l'exercice qui aide le mieux à vaincre le ''complexe d'infériorité''. Réciproquement, cette marche qui ne désire pas de but, cette ''marche pure'' comme une ''poésie pure'', donne de constantes et d'immédiates impressions de volonté de puissance.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'appel de l'eau réclame en quelque sorte un don total, un don intime. L'eau veut un habitant.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le poème est essentiellement ''une aspiration à des images nouvelles''. Il correspond au besoin essentiel de ''nouveauté'' qui caractérise le psychisme humain.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Par l'imagination nous abandonnons le cours ordinaire des choses. Percevoir et imaginer sont aussi antithétiques que présence et absence. Imaginer c'est s'absenter, c'est s'élancer vers une vie nouvelle.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Parce que le poète nous découvre une nuance ''fugitive'', nous apprenons à imaginer toute nuance comme un ''changement''. Seule l'imagination peut voir les nuances, elle les saisit au passage d'une couleur à une autre.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Un être privé de la ''fonction de l'irréel'' est un névrosé aussi bien que l'être privé de la ''fonction du réel''. On peut dire qu'un trouble de la fonction de l'irréel retentit sur la fonction du réel. Si la fonction ''d'ouverture'', qui est proprement la fonction de l'imagination, se fait mal, la perception elle-même reste obtuse. On devra trouver une filiation régulière du réel à l'imaginaire.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "M. Edouard Le Roy a apporté de nombreux développements à la théorie de la matière chez Bergson. Il a montré que l'habitude était l'inertie du devenir psychique. De notre point de vue très particulier, l'habitude est l'exacte antithèse de l'imagination créatrice. L'image habituelle arrête les forces imaginantes. L'image apprise dans les livres, surveillée et critiquée par les professeurs, bloque l'imagination.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'homme en tant qu'homme ne peut vivre horizontalement. Son repos, son sommeil est le plus souvent une chute.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le verbe n’est-il pas la première allégresse ? La parole a une tonicité si elle espère.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Les images poétiques sont [...] toutes, pour Shelley, des ''opérateurs d'élévation''. Autrement dit, les images poétiques sont des ''opérations'' de l'esprit humain dans la mesure où elles nous allègent, où elles nous soulèvent, où elles nous élèvent. Elles n'ont qu'un axe de référence : l'axe vertical. Elles sont essentiellement aériennes. Si une seule image du poème manque à remplir cette fonction d'allègement, le poème s'écrase, l'homme est rendu à son esclavage, la chaîne le blesse.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La poétique de Shelley est une poétique de l'immensité bercée\". Le monde est pour Shelley un immense berceau — un berceau cosmique — d'où, sans cesse, s'envolent des rêves.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le paon est éminemment ''terrestre''. C'est un musée minéral.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Imaginer, c'est hausser le réel d'un ton.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Pour comprendre Blake, il faut que le lecteur s'apprenne à alerter tous les muscles du corps, et qu'il y joigne essentiellement à l'effort un souffle, un souffle de colère. Il arrivera ainsi à donner son vrai sens à ce qu'on pourrait appeler pour caractériser l'inspiration blakienne : l'inspiration rauque.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Henri Wallon a montré que l'agoraphobie n'était, au fond, qu'une variété de la peur de tomber. Elle n'est pas une peur de rencontrer des hommes, mais une peur de ne pas rencontrer d'appui.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "N'imagine pas qui veut ! Il ne s'agit pas d'imaginer n'importe quoi. La révolution euphorique se trouve au contraire devant cette tâche difficile qu'est l'unité d'imagination\". Pour gagner cette unité d'imagination, pour avoir le schème dynamique directeur du bonheur, il faut donc revenir à l'un des grands principes de l'imagination matérielle. Ce n'est pas là une condition suffisante du bonheur, mais c'est une condition nécessaire. L'on ne peut être heureux avec une \"imagination divisée\". La sublimation — tâche positive de l'imagination — ne peut être occasionnelle, hétéroclite, scintillante. Un principe de calme doit venir auréoler toutes les passions, même les passions de la force.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Dans le règne de l'imagination, l'air nous libère des rêveries substantielles, intimes, digestives. Il nous libère de notre attachement aux matières : il est donc la matière de notre liberté. A Nietzsche, l'air n'apporte ''rien''. Il ne donne ''rien''. Il est l'immense gloire d'un Rien. Mais de ''rien donner'' n'est-il pas le plus grand des dons. Le grand donateur aux mains vides nous débarrasse des désirs de la main tendue. Il nous habitue à ne rien recevoir, donc à tout prendre. [...] l'air est la véritable patrie du ''prédateur''. L'air est cette ''substance infinie'' qu'on traverse d'un trait, dans une liberté offensive et triomphante, comme la foudre, comme l'aigle, comme la flèche, comme le regard impérieux et souverain. Dans l'air on emporte au grand jour sa victime. On ne se cache pas.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le nietzschéisme est essentiellement un vertige surmonté. Près de l'abîme, Nietzsche vient chercher des images dynamiques d'ascension. Le réel du gouffre donne à Nietzsche, par une dialectique bien connue de l'orgueil, la conscience d'être une force surgissante.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La volonté nietzschéenne prend appui sur sa propre vitesse. Elle est une accélération du devenir qui n'a pas besoin de matière. Il semble que l'abîme, comme un arc toujours tendu, serve à Nietzsche à lancer ses flèches vers le haut. Près de l'abîme, le destin humain est de tomber. Près de l'abîme, le destin du surhomme est de jaillir, tel un pin vers le ciel bleu.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Sur cet immense tableau d'une nuit céruléenne, la rêverie mathématicienne a écrit des épures. Elles sont toutes fausses, délicieusement fausses, ces constellations ! Elles unissent, dans une même figure, des astres totalement étrangers. Entre des points réels, entre des étoiles isolées comme des diamants solitaires, le rêve constellant tire des lignes imaginaires. Dans un pointillisme réduit au minimum, ce grand maître de peinture abstraite qu'est le rêve voit tous les animaux du zodiaque.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "« Connaître » les constellations, les nommer comme dans les livres, projeter sur le ciel une carte scolaire du ciel, c'est brutaliser nos forces imaginaires, c'est nous enlever le bienfait de l'onirisme étoilé. Sans le poids de ces mots qui «s oulagent la mémoire », — la mémoire des mots, cette grande paresseuse qui refuse de rêver, — chaque nuit nouvelle serait pour nous une rêverie nouvelle, une cosmogonie renouvelée. Le conscient mal fait, le conscient tout fait est aussi nocif pour l'âme rêvante que l'inconscient amorphe ou déformé. Le psychisme doit trouver l'équilibre entre l'imaginé et le connu. Cet équilibre ne se satisfait pas de vaines substitutions où, subitement, les forces imaginantes se voient associées à des schémas arbitraires. L'imagination est une force première. Elle doit naître dans la solitude de l'être imaginant.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'imagination a besoin d'un allongement, d'un ralenti. Et en particulier, plus que tout autre, l'imagination de la matière nocturne a besoin de lenteur.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Le ciel étoilé est le plus lent des mobiles naturels.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Dans la contemplation, l'être rêvant apprend à s'animer de l'intérieur, il apprend à vivre le temps régulier, le temps sans élan et sans heurt. C'est le ''temps de la nuit''.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "[...] la rêverie des nuages reçoit un caractère psychologique particulier : elle est une rêverie sans responsabilité.\nL'aspect immédiat de cette rêverie, c'est d'être, comme il a été souvent dit, un jeu aisé des formes. Les nuages sont une matière d'imagination pour un pétrisseur paresseux. On les rêve comme une ouate légère qui se travaillerait elle-même.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La première tâche du poète est de désancrer en nous une matière qui veut rêver.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Impossible d'imaginer un petit nuage qui disparaisse en tombant. Le petit nuage, le nuage léger est le thème d'ascension la plus régulière, la plus sûre. Il est un conseil permanent de sublimation.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La poésie totale, la ''poésie parfaite'', dit Hugo von Hofmannsthal, « c'est le corps d'un elfe, transparent comme l'air, le messager vigilant qui porte à travers les airs une parole magique : en passant il s'empare du mystère de nuages, des étoiles, des cimes, des vents ; il transmet la formule magique fidèlement, mêlée cependant aux voix mystérieuses des nuages, des étoiles, des cimes et des vents ». Le messager ne fait plus qu'un avec le message. Le monde intime du poète rivalise avec l'univers.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La végétation ne connaît pas de contradiction. Il vient des nuages pour contredire le soleil du solstice. Aucune tempête n'empêche l'arbre, à son heure, de devenir vert.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Il n'y a pas de ''poésie'' antécédente à l'acte du verbe poétique. Il n'y a pas de réalité antécédente à l'image littéraire. L'image littéraire ne vient pas habiller une image nue, ne vient pas donner la parole à une image muette. L'imagination, en nous, parle, nos rêves parlent, nos pensées parlent. Toute activité humaine désire parler. Quand cette parole prend conscience de soi, alors l'activité humaine désire écrire, c'est-à-dire agencer les rêves et les pensées. L'imagination s'enchante de l'image littéraire. La littérature n'est donc le succédané d'aucune autre activité. Elle achève un désir humain. Elle représente une ''émergence'' de l'imagination.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'image littéraire promulgue des sonorités qu'il faut appeler, sur un mode à peine métaphorique, des ''sonorités écrites''. Une sorte d'oreille abstraite, apte à saisir des voix tacites, s'éveille en écrivant ; elle impose des canons qui précisent les genres littéraires. Par un langage amoureusement écrit, une sorte d'audition projetante, sans nulle passivité, se prépare. La ''Natura audiens'' prend le pas sur la ''Natura audita''. La plume chante !", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Comme elle est injuste, la critique qui ne voit dans le langage qu'une sclérose de l'expérience intime ! Au contraire, le langage est toujours un peu en avant de notre pensée, un peu plus bouillonant que notre amour. Il est la belle fonction de l'imprudence humaine, la vantardise dynamogénique de la volonté, ce qui exagère la puissance. A plusieurs reprises, au cours de cet essai, nous avons souligné le caractère dynamique de l'exagération imaginaire. Sans cette exagération, la vie ne peut pas se développer. En toutes circonstances, la vie prend trop pour avoir assez. Il faut que l'imagination prenne trop pour que la pensée ait assez. Il faut que la volonté imagine trop pour réaliser assez.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'imagination n'est rien d'autre que le sujet transporté dans les choses.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'imagination […] trouve plus de réalité à ce qui se cache qu'à ce qui se montre.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "L'imagination créatrice a de tout autres fonctions que celles de l'imagination reproductrice. À elle appartient cette ''fonction de l'irréel'' qui est psychiquement aussi utile que la ''fonction du réel'' si souvent évoquée par les psychologues pour caractériser l'adaptation d'un esprit à une réalité estampillée par les valeurs sociales.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Ainsi une statue, c’est aussi bien l’être humain immobilisé par la mort que la pierre qui veut naître dans une forme humaine. La rêverie qui contemple une statue est alors animée dans un rythme d’immobilisation et de mise en mouvement. Elle est naturellement livrée à une ambivalence de la mort et de la vie.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La pensée pure doit commencer par un refus de la vie. La première pensée claire, c'est la pensée du néant.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La devise du mollusque serait alors : il faut vivre pour bâtir sa maison et non bâtir sa maison pour y vivre.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "La paix de la forêt est […] une paix de l'âme. La forêt est un état d'âme.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Si l'on nous demandait le bienfait le plus précieux de la maison, nous dirions : la maison abrite la rêverie, la maison protège le rêveur, la maison nous permet de rêver en paix.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Les mots — je l'imagine souvent — sont de petites maisons, avec cave et grenier. Le sens commun séjourne au rez-de chaussée, toujours prêt au « commerce extérieur », de plain-pied avec autrui, ce passant qui n'est jamais un rêveur. Monter l'escalier dans la maison du mot c'est, de degré en degré, abstraire. Descendre à la cave, c'est rêver, c'est se perdre dans les lointains couloirs d'une étymologie incertaine, c'est chercher dans les mots des trésors introuvables. Monter et descendre, dans les mots mêmes, c'est la vie du poète. Monter trop haut, descendre trop bas est permis au poète qui joint le terrestre à l'aérien. Seul le philosophe sera-t-il condamné par ses pairs à vivre toujours au rez-de-chaussée ?", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "C'est toute l'âme qui se livre avec l'univers poétique du poète. À l'esprit reste la tâche de faire des systèmes, d'agencer des expériences diverses pour tenter de comprendre l'univers. À l'esprit convient la patience de s'instruire tout le long du passé du savoir. Le passé de l'âme est si loin ! L'âme ne vit pas au fil du temps. Elle trouve son repos dans les univers que la rêverie imagine […] Les idées s'affinent et se multiplient dans le commerce des esprits. Les images, dans leur splendeur, réalisent une très simple communion des âmes. […] Et la langue des poètes doit être apprise directement, très précisément comme le langage des âmes.", Author = "Gaston Bachelard" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Gaston_Bachelard", Text = "Nous allons lui mettre dix et demi, c'est ce que nous méritons tous.", Author = "Gaston Bachelard" },
        };
    }
}